/* V304 · Coleção independente Bruno Santos CD. Print fornecido pelo usuário.
 * Não altera 246 cartas, builds, progressos nem os acervos de terceiros.
 * OVR 106 é apenas texto observado. Nível máximo 35 e 68 PP confirmados pelo proprietário;
 * Card ID/edição continuam sem confirmação.
 */
(function(g,f){'use strict';const a=f(g);
 if(typeof module==='object'&&module.exports)module.exports=a;
 if(g)g.CRAQUE_BRUNO_V304=a;
})(typeof window!=='undefined'?window:null,function(g){'use strict';
const NAME='Bruno Santos CD';
const CARD_ID='bruno-santos-cd:zico:106-sa:print-20261021';
const MARK='scoutpro:v304:bruno-santos-cd-initialized';
const CONFIRMED_LEVEL=35,CONFIRMED_PP=68;
const SOURCE_NOTE='Confirmação do proprietário em 22/10/2026: nível MÁXIMO 35 e 68 PP para este Zico do acervo Bruno Santos CD. Card ID e edição oficial continuam pendentes.';
const SOURCE_MARK='scoutpro:v310:zico-level-pp-user-confirmed';
const PHOTO='data:image/jpeg;base64,';
const NOTE='Origem: print enviado em 21/10/2026. Apresenta Zico 106 SA, Armador criativo, indicação Básico e 362 partidas. Card ID, edição oficial, skills e ímpetos pendentes. Nível máximo 35 e 68 PP confirmados posteriormente pelo proprietário. O segundo print mostra Zico 108 MAT de outra fonte e não comprova ser esta edição. Inclusão no acervo Bruno Santos CD solicitada pelo usuário; propriedade da conta ainda não comprovada.';
const normalize=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase().replace(/\s+/g,' ');
function useTraining(card,training,deps){
 if(!training||typeof training.generate!=='function')return card;
 try{return {...card,analysis:training.generate(card,deps)}}
 catch(_){return card} // painel calcula on-demand e nunca impede salvar a carta.
}
function candidate(card,ownerId){
 if(card.ownerId!==ownerId||normalize(card.name)!=='zico'||card.position!=='SA')return false;
 // ID estável da edição V304 OU print específico V304, não qualquer carta chamada Zico.
 return card.id===CARD_ID||
   (card.cardId===''&&String(card.edition).includes('106 SA')&&
    String(card.notes).includes('362 partidas'));
}
function confirmExisting(source,api,storage,training,deps){
 const owner=source.owners.find(x=>normalize(x.name)===normalize(NAME));
 if(!owner)return {data:source,changed:false,reason:'colecao_ausente'};
 const matches=source.cards.filter(c=>candidate(c,owner.id));
 if(matches.length!==1)return {data:source,changed:false,reason:'edicao_ambigua_ou_ausente'};
 const card=matches[0];
 if(card.cardId || (card.level!==null&&card.level!==CONFIRMED_LEVEL)||
    (card.pp!==null&&card.pp!==CONFIRMED_PP))
  return {data:source,changed:false,reason:'dados_manuais_preservados'};
 if(card.level===CONFIRMED_LEVEL&&card.pp===CONFIRMED_PP)
  return {data:source,changed:false,reason:'ja_confirmado'};
 // Uma proposta calculada anteriormente pode representar alterações manuais.
 // Não substituir nenhuma ficha que já contenha níveis efetivamente distribuídos.
 if(card.analysis?.profiles&&Object.values(card.analysis.profiles).some(p=>p.status==='hipotese'))
  return {data:source,changed:false,reason:'ficha_existente_protegida'};
 let notes=String(card.notes||'')
  .replace('nível, PP, skills','skills')
  .replace('Nível e PP pendentes.','');
 if(!notes.includes(SOURCE_NOTE))notes=(notes?notes+' ':'')+SOURCE_NOTE;
 let next=api.saveCard(source,useTraining({...card,level:CONFIRMED_LEVEL,pp:CONFIRMED_PP,
  notes,analysis:null},training,deps));
 next=api.write(storage,next);
 try{storage.setItem(SOURCE_MARK,'ok')}catch(_){}
 return {data:next,changed:true,reason:'nivel_pp_confirmados',ownerId:owner.id,cardId:card.id};
}
function seed(data,api,storage,training,deps){
 if(!api||!storage)return {data,changed:false,reason:'api_indisponivel'};
 let source=api.validate(data);
 if(storage.getItem(MARK)==='ok')
  return confirmExisting(source,api,storage,training,deps);
 let owner=source.owners.find(x=>normalize(x.name)===normalize(NAME));
 let next=source;
 if(!owner){next=api.addOwner(next,NAME);owner=next.owners.find(x=>normalize(x.name)===normalize(NAME));}
 const already=next.cards.find(x=>x.ownerId===owner.id&&(
  x.id===CARD_ID||normalize(x.name)==='zico'&&x.position==='SA'&&(
   x.notes?.includes('106 SA')||x.edition?.includes('106 SA'))));
 if(!already){
  const card=useTraining({id:CARD_ID,ownerId:owner.id,name:'Zico',
   edition:'Edição não identificada · print 106 SA',position:'SA',
   style:'Armador criativo',cardId:'',rarity:'',level:CONFIRMED_LEVEL,pp:CONFIRMED_PP,
   nativeSkills:'',skills:'',booster:'',fixedBooster:'',boosterSlot:'pendente',
   trainingLevels:'',notes:NOTE+' '+SOURCE_NOTE,image:PHOTO},training,deps);
  next=api.saveCard(next,card);
 }
 const changed=next!==source;
 if(changed)source=api.write(storage,next);
 storage.setItem(MARK,'ok');
 if(!already){
  try{storage.setItem(SOURCE_MARK,'ok')}catch(_){}
  return {data:source,changed,ownerId:owner.id,cardId:CARD_ID,reason:'cadastrado_com_pp_confirmados'};
 }
 const patch=confirmExisting(source,api,storage,training,deps);
 return {...patch,changed:changed||patch.changed,ownerId:owner.id,cardId:already.id};
}
return Object.freeze({NAME,CARD_ID,MARK,PHOTO,NOTE,CONFIRMED_LEVEL,CONFIRMED_PP,SOURCE_NOTE,SOURCE_MARK,normalize,candidate,confirmExisting,seed});
});
